def count_odd_ranks_ax_by_manual(max_val, a, b):
    odd_count = 0
    for x in range(max_val):
        for y in range(max_val):
            val = a * x + b * y
            rank = 0
            K = val - 1
            if K >= 0:
                for x_prime in range(K // a + 1):
                    rank += (K - a * x_prime) // b + 1
            for y_prime in range(max_val):
                x_prime_num = val - b * y_prime
                if x_prime_num >= 0 and x_prime_num % a == 0:
                    x_prime = x_prime_num // a
                    if x_prime < x:
                        rank += 1
            if rank % 2 != 0:
                odd_count += 1
    return odd_count

